/**
 * TitleMotion - Generated by Title Motion Lab
 *
 * Usage:
 *   import { TitleMotion } from './TitleMotion';
 *
 *   // Use with default text
 *   <TitleMotion />
 *
 *   // Use with custom text
 *   <TitleMotion text="Your Custom Title" />
 *
 *   // Control playback
 *   <TitleMotion play={isPlaying} onComplete={() => console.log('done')} />
 *
 * Dependencies: framer-motion
 *   npm install framer-motion
 */

'use client';

import { useState, useEffect, useRef, useMemo } from 'react';
import { motion } from 'framer-motion';

// Seeded PRNG for deterministic randomness
function createPRNG(seed: number) {
  let state = seed;
  return function random() {
    state |= 0;
    state = (state + 0x6d2b79f5) | 0;
    let t = Math.imul(state ^ (state >>> 15), 1 | state);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

// Configuration
const CONFIG = {
  text: "Rewiring how designers think about software in the age of AI",
  preset: "scramble",
  duration: 1200,
  stagger: 25,
  delay: 0,
  seed: 87830,
  // Typography
  fontFamily: "Inter, system-ui, sans-serif",
  fontSize: 900,
  fontWeight: 700,
  letterSpacing: '-0.02em',
  lineHeight: 1.1,
  textTransform: "none",
};

interface TitleMotionProps {
  text?: string;
  className?: string;
  style?: React.CSSProperties;
  play?: boolean;
  onComplete?: () => void;
}

// Scramble preset settings for word-based animation
// Character sets grouped by width for better visual consistency
const CHAR_WIDTH_MAP: Record<string, string> = {
  // Narrow chars -> narrow scramble options
  'i': 'ijl',
  'j': 'ijl',
  'l': 'ijl',
  'I': 'IJL',
  'J': 'IJL',
  'L': 'IJL',
  // Medium-narrow
  't': 'tfr',
  'f': 'tfr',
  'r': 'tfr',
  // Wide chars -> wide scramble options
  'w': 'wmn',
  'm': 'wmn',
  'W': 'WMN',
  'M': 'WMN',
  // Default medium chars
  'default_lower': 'abcdeghnopqsuvxyz',
  'default_upper': 'ABCDEGHNOPQSUVXYZ',
};

const SCRAMBLE_CONFIG = {
  intensity: 1,
  steps: 60,
  revealMode: "ltr",
};

function generateScrambledWord(word: string, rng: () => number): string {
  return word.split('').map(char => {
    if (char === ' ') return ' ';

    // Check if this char has a specific width group
    const widthGroup = CHAR_WIDTH_MAP[char];
    if (widthGroup) {
      const arr = widthGroup.split('');
      return arr[Math.floor(rng() * arr.length)];
    }

    // Use default charset based on case
    const isUpper = char === char.toUpperCase() && char !== char.toLowerCase();
    const defaultSet = isUpper ? CHAR_WIDTH_MAP['default_upper'] : CHAR_WIDTH_MAP['default_lower'];
    const arr = defaultSet.split('');
    return arr[Math.floor(rng() * arr.length)];
  }).join('');
}

function generateRevealOrder(length: number, mode: string, seed: number): number[] {
  const indices = Array.from({ length }, (_, i) => i);
  switch (mode) {
    case 'ltr': return indices;
    case 'rtl': return [...indices].reverse();
    case 'center': {
      const center = Math.floor(length / 2);
      const result = [center];
      for (let offset = 1; result.length < length; offset++) {
        if (center - offset >= 0) result.push(center - offset);
        if (center + offset < length) result.push(center + offset);
      }
      return result;
    }
    case 'random': {
      const random = createPRNG(seed + 12345);
      for (let i = indices.length - 1; i > 0; i--) {
        const j = Math.floor(random() * (i + 1));
        [indices[i], indices[j]] = [indices[j], indices[i]];
      }
      return indices;
    }
    default: return indices;
  }
}

export function TitleMotion({
  text = CONFIG.text,
  className = '',
  style = {},
  play = true,
  onComplete,
}: TitleMotionProps) {
  const words = useMemo(() => text.split(' '), [text]);
  const revealOrder = useMemo(
    () => generateRevealOrder(words.length, SCRAMBLE_CONFIG.revealMode, CONFIG.seed),
    [words.length]
  );

  const getInitialStates = () => {
    const initRandom = createPRNG(CONFIG.seed);
    return words.map((word, index) => {
      return {
        target: word,
        current: generateScrambledWord(word, initRandom),
        isRevealed: false,
        revealOrder: revealOrder.indexOf(index),
      };
    });
  };

  const [wordStates, setWordStates] = useState(getInitialStates);
  const tickRef = useRef(0);
  const intervalRef = useRef<NodeJS.Timeout | null>(null);

  useEffect(() => {
    if (!play) return;

    tickRef.current = 0;
    setWordStates(getInitialStates());
    const tickInterval = CONFIG.duration / SCRAMBLE_CONFIG.steps;

    const delayTimeout = setTimeout(() => {
      intervalRef.current = setInterval(() => {
        tickRef.current++;
        const currentTick = tickRef.current;
        const totalTicks = SCRAMBLE_CONFIG.steps;

        setWordStates(prev => {
          const tickRandom = createPRNG(CONFIG.seed + currentTick * 1000);

          const newStates = prev.map((state) => {
            if (state.isRevealed) return state;
            const revealThreshold = (state.revealOrder / words.length) * totalTicks * SCRAMBLE_CONFIG.intensity;
            const shouldReveal = currentTick >= revealThreshold + (totalTicks * (1 - SCRAMBLE_CONFIG.intensity));

            if (shouldReveal) {
              return { ...state, current: state.target, isRevealed: true };
            }
            return { ...state, current: generateScrambledWord(state.target, tickRandom) };
          });

          if (newStates.every(s => s.isRevealed)) {
            if (intervalRef.current) clearInterval(intervalRef.current);
            setTimeout(() => onComplete?.(), 50);
          }
          return newStates;
        });
      }, tickInterval);
    }, CONFIG.delay);

    return () => {
      clearTimeout(delayTimeout);
      if (intervalRef.current) clearInterval(intervalRef.current);
    };
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [play, text]);

  return (
    <span
      className={className}
      style={{
        display: 'inline',
        fontFamily: CONFIG.fontFamily,
        fontWeight: CONFIG.fontWeight,
        letterSpacing: CONFIG.letterSpacing,
        lineHeight: CONFIG.lineHeight,
        textTransform: CONFIG.textTransform as React.CSSProperties['textTransform'],
        ...style,
      }}
    >
      {wordStates.map((state, index) => (
        <span key={index}>
          <motion.span
            initial={{ opacity: 0.6 }}
            animate={{ opacity: state.isRevealed ? 1 : 0.7 }}
            transition={{ duration: 0.15 }}
            style={{
              display: 'inline',
            }}
          >
            {state.current}
          </motion.span>
          {index < wordStates.length - 1 && ' '}
        </span>
      ))}
    </span>
  );
}
